// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// --- Seed roles and sample data ---
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    foreach (var role in new[] { "Dispatcher", "Customer" })
    {
        if (!await roleManager.RoleExistsAsync(role))
            await roleManager.CreateAsync(new IdentityRole(role));
    }

    if (!db.Shipments.Any())
    {
        var rng = new Random(42);
        var cities = new[]
        {
            "New York", "Los Angeles", "Chicago", "Houston", "London",
            "Tokyo", "Sydney", "Berlin", "São Paulo", "Mumbai"
        };
        var descriptions = new[]
        {
            "Electronics", "Furniture", "Medical Supplies",
            "Auto Parts", "Clothing", "Food Products"
        };
        var statuses = Enum.GetValues<ShipmentStatus>();

        for (int i = 1; i <= 25; i++)
        {
            var status = statuses[rng.Next(statuses.Length)];
            var shipped = DateTime.UtcNow.AddDays(-rng.Next(1, 15));
            var estimated = shipped.AddDays(rng.Next(3, 14));
            db.Shipments.Add(new Shipment
            {
                TrackingNumber = $"SHP-{1000 + i}",
                Origin = cities[rng.Next(cities.Length)],
                Destination = cities[rng.Next(cities.Length)],
                Status = status,
                ShippedDate = shipped,
                EstimatedDelivery = estimated,
                ActualDelivery = status == ShipmentStatus.Delivered
                    ? estimated.AddDays(rng.Next(-2, 3)) : null,
                RecipientName = $"Customer {i}",
                Description = descriptions[rng.Next(descriptions.Length)]
            });
        }
        db.SaveChanges();
    }
}

// --- API endpoints ---
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments
        .OrderByDescending(s => s.ShippedDate)
        .Select(s => s.ToDto())
        .ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapGet("/api/shipments/{id:int}", async (int id, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment.ToDto());
}).RequireAuthorization();

app.MapPut("/api/shipments/{id:int}", async (int id, ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Origin = dto.Origin;
    shipment.Destination = dto.Destination;
    shipment.Status = dto.Status;
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.ActualDelivery = dto.ActualDelivery;
    shipment.RecipientName = dto.RecipientName;
    shipment.Description = dto.Description;
    await db.SaveChangesAsync();
    return Results.Ok(shipment.ToDto());
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment.ToDto());
});

app.Run();

