using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    foreach (var role in new[] { "Dispatcher", "Customer" })
    {
        if (!await roleManager.RoleExistsAsync(role))
            await roleManager.CreateAsync(new IdentityRole(role));
    }

    if (!db.Shipments.Any())
    {
        var rng = new Random(42);
        var cities = new[]
        {
            "New York", "Los Angeles", "Chicago", "Houston", "London",
            "Tokyo", "Sydney", "Berlin", "São Paulo", "Mumbai"
        };
        var descriptions = new[]
        {
            "Electronics", "Furniture", "Medical Supplies",
            "Auto Parts", "Clothing", "Food Products"
        };
        var statuses = Enum.GetValues<ShipmentStatus>();

        for (int i = 1; i <= 25; i++)
        {
            var status = statuses[rng.Next(statuses.Length)];
            var shipped = DateTime.UtcNow.AddDays(-rng.Next(1, 15));
            var estimated = shipped.AddDays(rng.Next(3, 14));
            db.Shipments.Add(new Shipment
            {
                TrackingNumber = $"SHP-{1000 + i}",
                Origin = cities[rng.Next(cities.Length)],
                Destination = cities[rng.Next(cities.Length)],
                Status = status,
                ShippedDate = shipped,
                EstimatedDelivery = estimated,
                ActualDelivery = status == ShipmentStatus.Delivered
                    ? estimated.AddDays(rng.Next(-2, 3)) : null,
                RecipientName = $"Customer {i}",
                Description = descriptions[rng.Next(descriptions.Length)]
            });
        }
        db.SaveChanges();
    }
}

