app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments
        .OrderByDescending(s => s.ShippedDate)
        .Select(s => s.ToDto())
        .ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapGet("/api/shipments/{id:int}", async (int id, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment.ToDto());
}).RequireAuthorization();

app.MapPut("/api/shipments/{id:int}", async (int id, ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    shipment.Origin = dto.Origin;
    shipment.Destination = dto.Destination;
    shipment.Status = dto.Status;
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.ActualDelivery = dto.ActualDelivery;
    shipment.RecipientName = dto.RecipientName;
    shipment.Description = dto.Description;
    await db.SaveChangesAsync();
    return Results.Ok(shipment.ToDto());
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment.ToDto());
});

